sys_rte_eb_script_operation.script:
/* global batch, output */

(function(batch, output) {
    const timeStamp = new Date().toISOString(); //performance.timeOrigin + performance.now();
    const infoStr = 'OHS - ' + timeStamp + ' - Get Position_Reporting_Position - ';
    let gsInfoStr = '';

    try {
        for (var i = 0; i < batch.length; i++) {
            //step1: access the input variables
            const posCode = batch[i].input; //Value of the source field.

            //step2: Your script/code goes here.
            if (posCode !== null && posCode !== '') {
                const grPosCode = new GlideRecord('x_hccc_base_org_position_code');
                const grPosRep = new GlideRecord('x_hccc_hoc_ohs_position_reports_to');

                grPosCode.get('code', posCode); //should only have 1
                grPosRep.get('position_code', grPosCode.getUniqueValue()); //could have multiple, but we only need 1

                //step3: set the output for each elements
                output[i] = grPosRep.getUniqueValue();
                gsInfoStr += '\n[i]: ' + i +
                    '\nposCode: ' + posCode +
                    ' - posCodeId: ' + grPosCode.getUniqueValue() +
                    ' - PosRepId: ' + output[i];
            }
        }
    } catch (e) {
        gs.error(infoStr + 'ERROR: ' + e + '\n\n\nInfo parse before Error: ' + gsInfoStr);
    }
    //gs.debug(infoStr + gsInfoStr);
})(batch, output);
